```sql
PRAGMA foreign_keys = ON;

CREATE TABLE participants (
  participant_id TEXT PRIMARY KEY,   -- e.g. 'P01'
  age INTEGER,
  grp TEXT
);

CREATE TABLE sessions (
  session_id INTEGER PRIMARY KEY,
  participant_id TEXT NOT NULL REFERENCES participants(participant_id),
  session_number INTEGER NOT NULL CHECK (session_number BETWEEN 1 AND 3),
  session_date TEXT,
  UNIQUE (participant_id, session_number)
);

CREATE TABLE stimuli (
  stimulus_id TEXT PRIMARY KEY,
  category TEXT,
  luminance REAL
);

CREATE TABLE trials (
  trial_id INTEGER PRIMARY KEY,
  session_id INTEGER NOT NULL REFERENCES sessions(session_id),
  stimulus_id TEXT NOT NULL REFERENCES stimuli(stimulus_id),
  trial_number INTEGER NOT NULL,
  rt_ms REAL,
  correct INTEGER CHECK (correct IN (0, 1)),
  UNIQUE (session_id, trial_number)
);
```

Note `PRAGMA foreign_keys = ON` must be run on every connection in SQLite, otherwise the references aren't enforced.

Same thing one level down: order_items reference orders. Delete bottom up:

```sql
BEGIN;
DELETE FROM order_items WHERE order_id IN (
  SELECT o.id FROM orders o JOIN customers c ON c.id = o.customer_id
  WHERE c.email LIKE '%@test.com');
DELETE FROM orders WHERE customer_id IN (
  SELECT id FROM customers WHERE email LIKE '%@test.com');
DELETE FROM customers WHERE email LIKE '%@test.com';
COMMIT;
```

If it fails again, there's another table pointing at one of these. You can list all FKs referencing `orders` with:

```sql
SELECT conrelid::regclass, conname FROM pg_constraint
WHERE confrelid = 'orders'::regclass AND contype = 'f';
```
